\label{tab:bh-fdr}
\begin{tabular}{@{}lcc@{}}
\toprule
Category & Bonf.\ sig. & BH-only sig. \\
\midrule
Per-condition Wilcoxon ($k{=}16$) & 10 & 2 \\
Imp vs.\ rand ($k{=}8$) & 8 & 0 \\
